/* Tests for the libwally-core-lite ZEC V6 codec (ZER-859), run by `make check`.
 * zec_v6_fixtures.h is generated by gen_c_fixtures.py from the shared vectors. */
#include <wally_core.h>
#include <wally_transaction.h>
#include <wally_psbt.h>
#include <wally_zcash.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "zec_v6_fixtures.h"

/* Real ZEC V4 PSBTs from wallet-gui zcash_decode_tests.cpp (1-in and 3-in). */
static const char *V4_PSBTS[] = {
    "",
    "",
};
#define V4_BRANCH_ID 0x5437F330u /* NU6.2, from the BitGo key in the fixtures */

static int failures = 0;
#define CHECK(cond, ...) do { if (!(cond)) { failures++; printf("  FAIL %s:%d: ", __FILE__, __LINE__); printf(__VA_ARGS__); printf("\n"); } } while (0)

static unsigned char *from_hex(const char *hex, size_t *len)
{
    size_t n = strlen(hex) / 2, written;
    unsigned char *b = malloc(n ? n : 1);
    if (wally_hex_to_bytes(hex, b, n, &written) != WALLY_OK || written != n) {
        free(b);
        return NULL;
    }
    *len = n;
    return b;
}

static void check_tx_roundtrip(const struct wally_tx *tx, uint32_t flags,
                               const unsigned char *expect, size_t expect_len, const char *what)
{
    unsigned char *out = malloc(expect_len + 16);
    size_t len = 0, written = 0;
    CHECK(wally_tx_get_length(tx, flags, &len) == WALLY_OK && len == expect_len,
          "%s: length %zu != %zu", what, len, expect_len);
    CHECK(wally_tx_to_bytes(tx, flags, out, expect_len + 16, &written) == WALLY_OK &&
          written == expect_len && !memcmp(out, expect, expect_len), "%s: bytes differ", what);
    free(out);
}

static struct wally_psbt *parse_psbt(const char *hex, int *ret)
{
    size_t len;
    unsigned char *b = from_hex(hex, &len);
    struct wally_psbt *psbt = NULL;
    *ret = wally_psbt_from_bytes(b, len, 0, &psbt);
    free(b);
    return psbt;
}

static void check_psbt_roundtrip(const struct wally_psbt *psbt, const char *hex, const char *what)
{
    size_t len, plen = 0, written = 0;
    unsigned char *expect = from_hex(hex, &len), *out;
    CHECK(wally_psbt_get_length(psbt, 0, &plen) == WALLY_OK && plen == len,
          "%s: psbt length %zu != %zu", what, plen, len);
    out = malloc(len + 16);
    CHECK(wally_psbt_to_bytes(psbt, 0, out, len + 16, &written) == WALLY_OK && written == len &&
          !memcmp(out, expect, len), "%s: psbt bytes differ", what);
    free(out);
    free(expect);
}

static void test_v6_case(const struct zec_v6_case *c)
{
    size_t len;
    unsigned char *bytes = from_hex(c->tx_hex, &len);
    struct wally_tx *tx = NULL, *clone = NULL;
    struct wally_psbt *psbt;
    int ret;

    printf("%s\n", c->name);

    CHECK(zec_v6_detect_header(bytes, len), "detect");
    CHECK(!zec_v4_detect_header(bytes, len), "v4 detect must be false");

    /* Raw tx */
    ret = wally_tx_from_bytes(bytes, len, WALLY_TX_FLAG_ZEC_V6, &tx);
    CHECK(ret == WALLY_OK && tx, "parse ret=%d", ret);
    if (tx) {
        CHECK(tx->version == 0x80000006u, "version 0x%08x", tx->version);
        CHECK(tx->version_group_id == ZEC_V6_VERSION_GROUP_ID, "group 0x%08x", tx->version_group_id);
        CHECK(tx->consensus_branch_id == c->branch_id, "branch 0x%08x", tx->consensus_branch_id);
        CHECK(tx->locktime == c->lock_time, "locktime %u", tx->locktime);
        CHECK(tx->expiry_height == c->expiry_height, "expiry %u", tx->expiry_height);
        CHECK(tx->num_inputs == c->num_inputs && tx->num_outputs == c->num_outputs,
              "counts %zu/%zu", tx->num_inputs, tx->num_outputs);
        CHECK(tx->outputs[0].satoshi == c->first_output_value, "output 0 value");
        check_tx_roundtrip(tx, WALLY_TX_FLAG_ZEC_V6, bytes, len, "tx");

        CHECK(wally_tx_clone_alloc(tx, 0, &clone) == WALLY_OK && clone, "clone");
        if (clone)
            check_tx_roundtrip(clone, WALLY_TX_FLAG_ZEC_V6, bytes, len, "clone");
        wally_tx_free(clone);
        wally_tx_free(tx);
        tx = NULL;
    }

    /* Rejections: shielded count, trailing byte, truncation, v4 flag on v6 bytes */
    {
        unsigned char *m = malloc(len + 1);
        size_t k;
        for (k = 1; k <= 4; k++) {
            memcpy(m, bytes, len);
            m[len - k] = 1;
            CHECK(wally_tx_from_bytes(m, len, WALLY_TX_FLAG_ZEC_V6, &tx) != WALLY_OK,
                  "nonzero shielded count %zu accepted", 5 - k);
            wally_tx_free(tx); tx = NULL;
        }
        memcpy(m, bytes, len);
        m[len] = 0;
        CHECK(wally_tx_from_bytes(m, len + 1, WALLY_TX_FLAG_ZEC_V6, &tx) != WALLY_OK, "trailing byte accepted");
        wally_tx_free(tx); tx = NULL;
        for (k = 1; k < len; k += (k < 24 ? 1 : 17)) {
            CHECK(wally_tx_from_bytes(bytes, len - k, WALLY_TX_FLAG_ZEC_V6, &tx) != WALLY_OK,
                  "truncated by %zu accepted", k);
            wally_tx_free(tx); tx = NULL;
        }
        memcpy(m, bytes, len);
        m[4] ^= 0xff; /* wrong group ID */
        CHECK(!zec_v6_detect_header(m, len), "wrong group ID detected as v6");
        free(m);
    }

    /* PSBT with witness_utxo only, branch from the tx */
    psbt = parse_psbt(c->psbt_hex, &ret);
    CHECK(ret == WALLY_OK && psbt, "psbt parse ret=%d", ret);
    if (psbt) {
        CHECK(psbt->tx->version_group_id == ZEC_V6_VERSION_GROUP_ID, "psbt group");
        CHECK(psbt->branch_id == c->branch_id, "psbt branch 0x%08x", psbt->branch_id);
        CHECK(psbt->inputs[0].witness_utxo && !psbt->inputs[0].utxo, "witness_utxo only");
        check_psbt_roundtrip(psbt, c->psbt_hex, "psbt");
        wally_psbt_free(psbt);
    }

    /* PSBT with a matching BitGo branch key */
    psbt = parse_psbt(c->psbt_bitgo_ok_hex, &ret);
    CHECK(ret == WALLY_OK && psbt && psbt->branch_id == c->branch_id, "bitgo-ok ret=%d", ret);
    if (psbt)
        check_psbt_roundtrip(psbt, c->psbt_bitgo_ok_hex, "psbt bitgo-ok");
    wally_psbt_free(psbt);

    /* PSBT with a conflicting BitGo branch key must be rejected */
    psbt = parse_psbt(c->psbt_bitgo_bad_hex, &ret);
    CHECK(ret != WALLY_OK && !psbt, "bitgo-bad accepted ret=%d", ret);
    wally_psbt_free(psbt);

    free(bytes);
}

static void test_v4_regression(void)
{
    size_t i;
    for (i = 0; i < sizeof(V4_PSBTS) / sizeof(V4_PSBTS[0]); i++) {
        int ret;
        struct wally_psbt *psbt = parse_psbt(V4_PSBTS[i], &ret);
        printf("v4_regression_%zu\n", i);
        CHECK(ret == WALLY_OK && psbt, "v4 psbt parse ret=%d", ret);
        if (!psbt)
            continue;
        CHECK(psbt->tx->version_group_id == ZEC_V4_VERSION_GROUP_ID, "v4 group");
        CHECK(psbt->tx->consensus_branch_id == 0, "v4 tx has no branch field");
        CHECK(psbt->branch_id == V4_BRANCH_ID, "v4 branch 0x%08x", psbt->branch_id);
        CHECK(psbt->inputs[0].utxo && psbt->inputs[0].utxo->version_group_id == ZEC_V4_VERSION_GROUP_ID,
              "v4 parent parsed");
        check_psbt_roundtrip(psbt, V4_PSBTS[i], "v4 psbt");
        wally_psbt_free(psbt);
    }
}

int main(void)
{
    size_t i;
    if (wally_init(0) != WALLY_OK)
        return 2;
    for (i = 0; i < sizeof(ZEC_V6_CASES) / sizeof(ZEC_V6_CASES[0]); i++)
        test_v6_case(&ZEC_V6_CASES[i]);
    test_v4_regression();
    printf(failures ? "FAILED: %d\n" : "ALL OK\n", failures);
    return failures ? 1 : 0;
}
